using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading;
using System.Web.Script.Serialization;
namespace PZ3D {
 static class ConfigurationLifecycleTests {
  static readonly JavaScriptSerializer Json=new JavaScriptSerializer();
  static Dictionary<string,object> D(object value){return Json.Deserialize<Dictionary<string,object>>(Json.Serialize(value));}
  static string[] Ids(object value){return ((IEnumerable)value).Cast<object>().Select(Convert.ToString).ToArray();}
  static Dictionary<string,object> P(params object[] pairs){var p=new Dictionary<string,object>();for(int i=0;i<pairs.Length;i+=2)p.Add((string)pairs[i],pairs[i+1]);return p;}
  static void Check(bool okay,string label){if(!okay)throw new Exception(label);Console.WriteLine("PASS: "+label);}
  sealed class Fixture {
   internal Engine E;internal string Shoot;
   internal Fixture(){string root=Path.Combine(LauncherTestPaths.Root,"life-"+Guid.NewGuid().ToString("N"));E=new Engine(Path.Combine(root,"steamapps/common/Game"),Path.Combine(root,"u"),Path.Combine(root,"d"),true){PresetSource=Path.Combine(root,"no-presets")};Put(E.Config,"{\"vmArgs\":[\"-Xmx2g\",\"-agentlib:zbNative\"]}");Put(Path.Combine(E.Game,"ProjectZomboid64.exe"),"fixture-never-executed");Put(Path.Combine(E.Game,"ZombieBuddy.jar"),"fixture");Put(Path.Combine(E.Game,"zbNative.dll"),"fixture");Put(Path.Combine(E.BuddyLib,"ZombieBuddy.jar"),"fixture");Put(Path.Combine(E.BuddyLib,"zbNative.dll"),"fixture");Put(Path.Combine(E.Workshop,"3809306528/mods/Viewpoint/42/mod.info"),"id=Viewpoint\nrequire=ZombieBuddy\n");Mod("A","");Mod("B","require=A\n");Mod("OrangeLauncherSessionUser","");Mod("ViewpointSurface","require=Viewpoint\n");Set("ZombieBuddy","Viewpoint","ViewpointSurface","B","A","OrangeLauncherSessionUser");Shoot=Path.Combine(root,"shoot");Put(Path.Combine(Shoot,"mods",ShootClient.Id,"common/mod.info"),"id="+ShootClient.Id+"\n");Put(Path.Combine(Shoot,"mods",ShootClient.Id,"42/media/java/client/ISeeThem.jar"),"fixture");}
   internal void Mod(string id,string extra){Put(Path.Combine(E.User,"mods",id,"42/mod.info"),"id="+id+"\n"+extra);}
   internal void Set(params string[] ids){Put(E.Mods,"mods\n{\n"+string.Concat(ids.Select(id=>" mod = "+id+",\n"))+"}\nmaps\n{\n map = Keep,\n}\ncustom\n{\n keep = yes,\n}\n");}
   internal void Stage(){LaunchProfiles.Stage(E,new ProfileLaunchRequest{Kind="save",Mode="Sandbox",Save="Fixture"});}
  }
  static void Put(string path,string text){Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path,text,new UTF8Encoding(false));}
  // A background cleanup must run after the complete component mutation, not between its read and write.
  static void CleanupRace(){var f=new Fixture();f.Set("A","B","OrangeLauncherSessionUser");Put(f.E.Config,"{\"vmArgs\":[\"-Xmx2g\"]}");f.Stage();Thread cleanup=null;Exception failure=null;bool completedInside=false;using(var started=new ManualResetEventSlim())using(var done=new ManualResetEventSlim()){
   f.E.Progress=(value,text)=>{if(text!="更新客户端默认模组列表")return;cleanup=new Thread(()=>{started.Set();try{LaunchProfiles.Recover(f.E,true);}catch(Exception ex){failure=ex;}finally{done.Set();}});cleanup.IsBackground=true;cleanup.Start();Check(started.Wait(5000),"owned cleanup thread reaches component write boundary");completedInside=done.Wait(500);};
   f.E.Switch(true,false);Check(cleanup!=null&&cleanup.Join(6000),"owned cleanup thread completes after component write");if(failure!=null)throw failure;
  }var ids=SaveProfiles.DefaultMods(File.ReadAllBytes(f.E.Mods));Check(!completedInside&&!LaunchProfiles.Pending(f.E)&&ids.SequenceEqual(new[]{"ZombieBuddy","Viewpoint","A","B","OrangeLauncherSessionUser"}),"component write and cleanup serialize without resurrecting the temporary bridge or losing ordinary mods");}
  // Every native default writer must participate in the same cleanup lease, including nested bridge removal.
  static void WriterLeases(){foreach(string kind in new[]{"chinese","shoot","bridge","models"}){var f=new Fixture();f.Set("ZombieBuddy","Viewpoint","LaoYuTranslationJava",ShootClient.Id,"PZVoxelStudioViewpoint","A");if(kind=="bridge")new PresentationBridge().Enable(f.E,f.Shoot);using(var c=new ModernController(f.E.Game,f.E.User,f.E.Data,true,null,null,null,null,true))using(var started=new ManualResetEventSlim())using(var done=new ManualResetEventSlim()){Exception failure=null;var writer=new Thread(()=>{started.Set();try{if(kind=="chinese")new ChinesePatch().Disable(f.E);else if(kind=="shoot")new ShootClient().Disable(f.E);else if(kind=="bridge")new PresentationBridge().Disable(f.E);else c.Execute("componentsAction",P("component","models","operation","uninstall"));}catch(Exception ex){failure=ex;}finally{done.Set();}});writer.IsBackground=true;bool waited;using(PlayProfileTransaction.Lock(f.E)){writer.Start();Check(started.Wait(5000),"owned writer enters "+kind);waited=!done.Wait(200);}Check(writer.Join(6000),"owned writer completes "+kind);if(failure!=null)throw failure;Check(waited,"default writer shares the cleanup mutex: "+kind);}}}
  // Session-only IDs must not become permanent named drafts, while similarly named user IDs stay intact.
  static void NamedProfiles(){var f=new Fixture();f.Stage();var live=SaveProfiles.DefaultMods(File.ReadAllBytes(f.E.Mods));Check(live.Contains("OrangeLauncherSession"),"active default keeps its temporary bridge");var list=D(ModConfigurations.List(f.E));Check(!Ids(list["activeMods"]).Contains("OrangeLauncherSession")&&Ids(list["activeMods"]).Contains("OrangeLauncherSessionUser"),"named profile seed excludes only the owned temporary ID");var saved=D(ModConfigurations.Save(f.E,P("id","","name","During session","stamp",list["stamp"],"mods",live)));Check(!Ids(saved["mods"]).Contains("OrangeLauncherSession"),"named save cannot persist the owned temporary ID from a raw default payload");LaunchProfiles.Recover(f.E,true);ModConfigurations.Activate(f.E,(string)saved["id"],(string)D(ModConfigurations.List(f.E))["stamp"],true);Check(SaveProfiles.DefaultMods(File.ReadAllBytes(f.E.Mods)).SequenceEqual(new[]{"ZombieBuddy","Viewpoint","ViewpointSurface","A","B","OrangeLauncherSessionUser"}),"named profile activates after cleanup with managed and ordinary dependency order intact");var ordinary=new Fixture();ordinary.Mod("OrangeLauncherSession","");var keep=D(ModConfigurations.Save(ordinary.E,P("id","","name","Ordinary user mod","stamp",D(ModConfigurations.List(ordinary.E))["stamp"],"mods",new[]{"OrangeLauncherSession","OrangeLauncherSessionUser"})));Check(Ids(keep["mods"]).SequenceEqual(new[]{"OrangeLauncherSession","OrangeLauncherSessionUser"}),"unowned ordinary IDs are never filtered from named profiles");}
  static void CapturedProfiles(){var f=new Fixture();f.Stage();var service=new PlayProfiles(f.E);var capture=D(service.Capture(P("stamp",D(service.List())["stamp"],"name","During session","targetKind","normal","targetId","")));var profile=D(capture["profile"]);Directory.CreateDirectory(Path.Combine(f.E.User,"Saves/Sandbox/Inherited"));var inherited=D(service.Capture(P("stamp",D(service.List())["stamp"],"name","Inherited session","targetKind","save","targetId","Sandbox/Inherited")));var inheritedProfile=D(inherited["profile"]);Check(Ids(inheritedProfile["mods"]).SequenceEqual(new[]{"B","A","OrangeLauncherSessionUser"}),"inherited-save capture excludes the owned bridge from fallback defaults");Check(Ids(profile["mods"]).SequenceEqual(new[]{"B","A","OrangeLauncherSessionUser"}),"play capture excludes the owned temporary ID and managed components only");var edit=new Dictionary<string,object>(profile);edit["mods"]=Ids(profile["mods"]).Concat(new[]{"OrangeLauncherSession"}).ToArray();edit["stamp"]=D(service.List())["stamp"];var saved=D(service.Save(edit));Check(!Ids(D(saved["profile"])["mods"]).Contains("OrangeLauncherSession"),"play save cannot persist the current owned temporary ID");var export=D(service.Export((string)profile["id"],(string)D(service.List())["stamp"]));var share=D(Json.DeserializeObject((string)export["json"]));share["mods"]=Ids(profile["mods"]).Concat(new[]{"OrangeLauncherSession"}).ToArray();var imported=D(service.Import(Json.Serialize(share),(string)D(service.List())["stamp"],true));Check(!Ids(D(imported["profile"])["mods"]).Contains("OrangeLauncherSession"),"play import excludes the current owned temporary ID from persistent membership");LaunchProfiles.Recover(f.E,true);var preview=D(service.Preview((string)profile["id"],(string)D(service.List())["stamp"]));Check(Convert.ToBoolean(preview["canApply"]),"captured play profile remains applicable after bridge cleanup");var inheritedPreview=D(service.Preview((string)inheritedProfile["id"],(string)D(service.List())["stamp"]));Check(Convert.ToBoolean(inheritedPreview["canApply"]),"inherited-save capture remains applicable after bridge cleanup");service.Apply((string)profile["id"],(string)preview["previewStamp"],true);Check(SaveProfiles.DefaultMods(File.ReadAllBytes(f.E.Mods)).SequenceEqual(new[]{"ZombieBuddy","Viewpoint","ViewpointSurface","A","B","OrangeLauncherSessionUser"}),"captured play profile applies final managed and ordinary dependency order");}
  static void SnapshotLeases(){foreach(string kind in new[]{"seed","capture"}){var f=new Fixture();f.Stage();var service=new PlayProfiles(f.E);string stamp=(string)D(service.List())["stamp"];using(var started=new ManualResetEventSlim())using(var done=new ManualResetEventSlim()){Exception failure=null;var reader=new Thread(()=>{started.Set();try{if(kind=="seed")ModConfigurations.List(f.E);else service.Capture(P("stamp",stamp,"name","Snapshot","targetKind","normal","targetId",""));}catch(Exception ex){failure=ex;}finally{done.Set();}});reader.IsBackground=true;bool waited;using(PlayProfileTransaction.Lock(f.E)){reader.Start();Check(started.Wait(5000),"owned persistent snapshot enters "+kind);waited=!done.Wait(200);}Check(reader.Join(6000),"owned persistent snapshot completes "+kind);if(failure!=null)throw failure;Check(waited,"persistent snapshot and ownership filter share the cleanup mutex: "+kind);}}}
  static string SessionNonce(Engine e){return Json.Deserialize<ProfileSessionRecord>(File.ReadAllText(Path.Combine(e.Data,"launch-sessions",LaunchProfiles.Key(e)+".json"))).Nonce;}
  static void WatchContention(){var f=new Fixture();f.Stage();string nonce=SessionNonce(f.E);using(var started=new ManualResetEventSlim())using(var done=new ManualResetEventSlim()){Exception failure=null;var watcher=new Thread(()=>{started.Set();try{LaunchProfiles.RecoverWatched(f.E,nonce);}catch(Exception ex){failure=ex;}finally{done.Set();}});watcher.IsBackground=true;bool returnedWhileHeld;using(PlayProfileTransaction.Lock(f.E)){watcher.Start();Check(started.Wait(5000),"owned watcher enters real long-lock boundary");returnedWhileHeld=done.Wait(5500);}Check(watcher.Join(10000),"owned watcher finishes when long-held mutex becomes available");if(failure!=null)throw failure;Check(!returnedWhileHeld&&!LaunchProfiles.Pending(f.E)&&!File.ReadAllText(f.E.Mods).Contains("mod = OrangeLauncherSession,"),"watch cleanup retries contention beyond five seconds and retires the same session");}
   var newer=new Fixture();newer.Stage();string old=SessionNonce(newer.E);using(var started=new ManualResetEventSlim())using(var done=new ManualResetEventSlim()){Exception failure=null;var watcher=new Thread(()=>{started.Set();try{LaunchProfiles.RecoverWatched(newer.E,old);}catch(Exception ex){failure=ex;}finally{done.Set();}});watcher.IsBackground=true;byte[] current;string next;using(PlayProfileTransaction.Lock(newer.E)){watcher.Start();Check(started.Wait(5000)&&!done.Wait(200),"old owned watcher waits behind the session mutex");LaunchProfiles.Recover(newer.E,true,old);newer.Stage();next=SessionNonce(newer.E);current=File.ReadAllBytes(newer.E.Mods);}Check(watcher.Join(10000),"old owned watcher finishes after session replacement");if(failure!=null)throw failure;Check(next!=old&&LaunchProfiles.Pending(newer.E)&&SessionNonce(newer.E)==next&&File.ReadAllBytes(newer.E.Mods).SequenceEqual(current),"old waiting watcher cannot clean a replacement session");LaunchProfiles.Recover(newer.E,true,next);}}
  public static void Run(){CleanupRace();WriterLeases();SnapshotLeases();NamedProfiles();CapturedProfiles();WatchContention();}
  [STAThread] public static int Main(string[] args){try{if(args.Length==0)Run();else if(args[0]=="race")CleanupRace();else if(args[0]=="writers")WriterLeases();else if(args[0]=="snapshots")SnapshotLeases();else if(args[0]=="named")NamedProfiles();else if(args[0]=="play")CapturedProfiles();else if(args[0]=="watch")WatchContention();else if(args[0]=="components"){ChinesePatchTests.Run();ShootClientTests.Run();PresentationBridgeTests.Run();}else throw new Exception("Unknown fixture case");Console.WriteLine("CONFIGURATION LIFECYCLE REGRESSIONS PASSED");return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}}
 }
}
